// Combine the generated email drafts into rows for 'Email Drafts' sheet
const items = $input.all();
const draftRows = [];

function formatEmailBody(text) {
  if (!text) return '';
  let cleaned = text.trim();

  // Fix AI grammar slip
  cleaned = cleaned.replace(/\bI runs\b/g, 'I run');
  cleaned = cleaned.replace(/\bWe runs\b/g, 'We run');

  // Ensure greeting is followed by double newline
  cleaned = cleaned.replace(/^(Hi [^,\n]+,?)\s*/i, '$1\n\n');
  cleaned = cleaned.replace(/^(Hey [^,\n]+,?)\s*/i, '$1\n\n');

  // Ensure CTA is separated by double newline
  cleaned = cleaned.replace(/\s*(Open to [^?\n]+\?)/i, '\n\n$1\n\n');
  cleaned = cleaned.replace(/\s*(Would you be open [^?\n]+\?)/i, '\n\n$1\n\n');

  // Strip out old/messy signature if Gemini appended one
  cleaned = cleaned.replace(/\s*(Best regards|Best Regards|Best|Regards|Sincerely|Cheers),?\s*Moshiur.*/is, '');

  // Normalize multiple newlines
  cleaned = cleaned.replace(/\n{3,}/g, '\n\n').trim();

  // Append clean, executive signature block
  cleaned += '\n\nBest regards,\nMoshiur Rahman\nSoftware Engineer & Studio Lead\nmoshiurbhau@gmail.com | https://labtoai.com';

  return cleaned;
}

for (let i = 0; i < items.length; i++) {
  const geminiRaw = items[i].json;
  const lead = $('Fetch \'New\' Leads').all()[i].json;

  let copy;
  try {
    const parts = geminiRaw.candidates[0].content.parts;
    const textPart = parts.find(p => p.text && p.text.trim().length > 0) || parts[0];
    let text = textPart.text.trim();
    if (text.startsWith("```json")) {
      text = text.replace(/^```json\s*/, "").replace(/\s*```$/, "");
    } else if (text.startsWith("```")) {
      text = text.replace(/^```\s*/, "").replace(/\s*```$/, "");
    }
    copy = JSON.parse(text.trim());
  } catch(e) {
    continue;
  }

  // Row 1: First Cold Email
  draftRows.push({
    json: {
      "Lead Email": lead["Email"],
      "Subject": copy.firstSubject,
      "Body": formatEmailBody(copy.firstBody),
      "Type": "First",
      "Approved?": "No",
      "Sent Date": ""
    }
  });

  // Row 2: Follow-up Email (Ready for later)
  draftRows.push({
    json: {
      "Lead Email": lead["Email"],
      "Subject": copy.followUpSubject || ("Re: " + copy.firstSubject),
      "Body": formatEmailBody(copy.followUpBody),
      "Type": "Follow-up",
      "Approved?": "No",
      "Sent Date": ""
    }
  });
}

return draftRows;

const items = $('Prepare Draft Rows').all();
const unique = {};
for (const item of items) {
  const email = item.json['Lead Email'];
  if (email && !unique[email]) {
    unique[email] = {
      json: {
        "Email": email,
        "Status": "Draft Created",
        "Next Action": "Review drafts in Email Drafts tab"
      }
    };
  }
}
return Object.values(unique);

const items = $('Filter Only Unsent').all();
const today = new Date().toISOString().split('T')[0];
return items.map(item => ({
  json: {
    "Lead Email": item.json['Lead Email'],
    "Subject": item.json['Subject'],
    "Sent Date": today
  }
}));

